package com.erudit.user;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;import com.erudit.user.controller.SocialController;import com.erudit.user.model.SocialModels.*;import com.erudit.user.openapi.model.*;import com.erudit.user.service.SocialService;import java.util.*;import org.junit.jupiter.api.Test;
class SocialControllerTest {@Test void exposesFriendsAndDevices(){var service=mock(SocialService.class);var controller=new SocialController(service);UUID user=UUID.randomUUID(),friend=UUID.randomUUID(),id=UUID.randomUUID();when(service.friends(user,0,20)).thenReturn(List.of(new PublicUser(friend,"Friend")));when(service.device(eq(user),any(),any())).thenReturn(new Device(id,user,"push-token","ANDROID"));assertThat(controller.listFriends(user,0,20).getBody()).hasSize(1);controller.requestFriend(new FriendRequest(friend),user);controller.decideFriendRequest(id,"accept",user);controller.removeFriend(friend,user);assertThat(controller.registerDevice(new DeviceRequest("push-token",DeviceRequest.PlatformEnum.ANDROID),user).getStatusCode().value()).isEqualTo(201);controller.revokeDevice(id,user);}}
